package com.mytransitgps.modules.ciq.collector;
import com.mytransitgps.modules.ciq.client.LtaEstimatedTravelTimesClient;import com.mytransitgps.modules.ciq.config.CiqProperties;import com.mytransitgps.modules.ciq.domain.EstimatedTravelTimeRecord;import com.mytransitgps.modules.ciq.parser.EstimatedTravelTimesParser;import com.mytransitgps.modules.ciq.persistence.*;import com.mytransitgps.modules.ciq.quality.EstimatedTravelTimesValidator;import com.mytransitgps.modules.ciq.storage.*;import com.mytransitgps.platform.collection.*;import org.slf4j.*;
/** API02 独立 Collector。 */
public class CiqEstimatedTravelTimesCollector implements DataCollector {private static final Logger log=LoggerFactory.getLogger(CiqEstimatedTravelTimesCollector.class);private final CiqPagedJsonCollectorSupport<EstimatedTravelTimeRecord> support;public CiqEstimatedTravelTimesCollector(LtaEstimatedTravelTimesClient client,CiqProperties p,CiqJsonStorageService storage,EstimatedTravelTimesParser parser,EstimatedTravelTimesValidator validator,EstimatedTravelTimesPersistenceService persistence,CiqAuditPersistenceService audit){support=new CiqPagedJsonCollectorSupport<>("API02",CiqApiCode.API02,CollectorCode.CIQ_EST_TRAVEL_TIMES,client,p,p.getCollectors().getEstimatedTravelTimes(),storage,parser::parse,validator::isValid,persistence==null?null:persistence::persist,audit,log);}public ModuleCode moduleCode(){return ModuleCode.CIQ;}public CollectorCode collectorCode(){return CollectorCode.CIQ_EST_TRAVEL_TIMES;}public CollectionResult collect(CollectionContext c){return support.collect(c);}}
